   1: use crate::charsets::{
   2:     charset_digits, charset_lowercase_hex, charset_lowercase_letters, charset_symbols,
   3:     charset_uppercase_hex, charset_uppercase_letters,
   4: };
   5: use crate::finder_errors::FinderError;
   6: use crate::finder_errors::FinderError::CliArgumentError;
   7: 
   8: /// A parsed mask is a sequence of positions, each with its own charset.
   9: #[derive(Clone, Debug)]
  10: pub struct ParsedMask {
  11:     pub positions: Vec<Vec<char>>,
  12: }
  13: 
  14: /// Resolve a built-in charset token character to its charset.
  15: fn resolve_builtin_token(token: char) -> Option<Vec<char>> {
  16:     match token {
  17:         'l' => Some(charset_lowercase_letters()),
  18:         'u' => Some(charset_uppercase_letters()),
  19:         'd' => Some(charset_digits()),
  20:         's' => Some(charset_symbols()),
  21:         'a' => {
  22:             let mut all = charset_lowercase_letters();
  23:             all.extend(charset_uppercase_letters());
  24:             all.extend(charset_digits());
  25:             all.extend(charset_symbols());
  26:             Some(all)
  27:         }
  28:         'h' => Some(charset_lowercase_hex()),
  29:         'H' => Some(charset_uppercase_hex()),
  30:         _ => None,
  31:     }
  32: }
  33: 
  34: /// Parse a custom charset definition string into a charset.
  35: ///
  36: /// Custom charset definitions can contain:
  37: /// - Built-in tokens like `?l`, `?d`, `?u`, etc. which expand to their charsets
  38: /// - Literal characters
  39: ///
  40: /// For example: `?l?d` expands to lowercase letters + digits,
  41: /// `aeiou` is just those 5 vowels, `?l@#$` is lowercase + @, #, $.
  42: pub fn parse_custom_charset(definition: &str) -> Result<Vec<char>, FinderError> {
  43:     let mut charset = Vec::new();
  44:     let mut chars = definition.chars();
  45: 
  46:     while let Some(c) = chars.next() {
  47:         if c == '?' {
  48:             match chars.next() {
  49:                 Some('?') => charset.push('?'),
  50:                 Some(token) => {
  51:                     if let Some(builtin) = resolve_builtin_token(token) {
  52:                         charset.extend(builtin);
  53:                     } else {
  54:                         return Err(CliArgumentError {
  55:                             message: format!(
  56:                                 "Unknown token '?{token}' in custom charset definition"
  57:                             ),
  58:                         });
  59:                     }
  60:                 }
  61:                 None => {
  62:                     return Err(CliArgumentError {
  63:                         message: "Custom charset definition ends with incomplete token '?'"
  64:                             .to_string(),
  65:                     });
  66:                 }
  67:             }
  68:         } else {
  69:             charset.push(c);
  70:         }
  71:     }
  72: 
  73:     if charset.is_empty() {
  74:         return Err(CliArgumentError {
  75:             message: "Custom charset definition is empty".to_string(),
  76:         });
  77:     }
  78: 
  79:     // deduplicate while preserving order
  80:     let mut seen = Vec::with_capacity(charset.len());
  81:     for c in charset {
  82:         if !seen.contains(&c) {
  83:             seen.push(c);
  84:         }
  85:     }
  86: 
  87:     Ok(seen)
  88: }
  89: 
  90: /// Custom charsets `?1` through `?4`, indexed 0-3.
  91: pub type CustomCharsets = [Option<Vec<char>>; 4];
  92: 
  93: /// Parse a mask pattern string into a `ParsedMask`.
  94: ///
  95: /// Mask tokens:
  96: /// - `?l` = lowercase letters (a-z)
  97: /// - `?u` = uppercase letters (A-Z)
  98: /// - `?d` = digits (0-9)
  99: /// - `?s` = symbols
 100: /// - `?a` = all printable (l+u+d+s)
 101: /// - `?h` = lowercase hex (0-9a-f)
 102: /// - `?H` = uppercase hex (0-9A-F)
 103: /// - `?1`..`?4` = custom charsets
 104: /// - `??` = literal '?'
 105: /// - Any other character = literal
 106: pub fn parse_mask(mask: &str, custom_charsets: &CustomCharsets) -> Result<ParsedMask, FinderError> {
 107:     let mut positions = Vec::new();
 108:     let mut chars = mask.chars();
 109: 
 110:     while let Some(c) = chars.next() {
 111:         if c == '?' {
 112:             match chars.next() {
 113:                 Some('?') => positions.push(vec!['?']),
 114:                 Some(token @ '1'..='4') => {
 115:                     let idx = (token as usize) - ('1' as usize);
 116:                     match &custom_charsets[idx] {
 117:                         Some(charset) => positions.push(charset.clone()),
 118:                         None => {
 119:                             return Err(CliArgumentError {
 120:                                 message: format!(
 121:                                     "Custom charset ?{token} used in mask but --customCharset{token} not provided"
 122:                                 ),
 123:                             });
 124:                         }
 125:                     }
 126:                 }
 127:                 Some(token) => {
 128:                     if let Some(builtin) = resolve_builtin_token(token) {
 129:                         positions.push(builtin);
 130:                     } else {
 131:                         return Err(CliArgumentError {
 132:                             message: format!("Unknown mask token '?{token}'"),
 133:                         });
 134:                     }
 135:                 }
 136:                 None => {
 137:                     return Err(CliArgumentError {
 138:                         message: "Mask ends with incomplete token '?'".to_string(),
 139:                     });
 140:                 }
 141:             }
 142:         } else {
 143:             positions.push(vec![c]);
 144:         }
 145:     }
 146: 
 147:     if positions.is_empty() {
 148:         return Err(CliArgumentError {
 149:             message: "Mask pattern is empty".to_string(),
 150:         });
 151:     }
 152: 
 153:     Ok(ParsedMask { positions })
 154: }
 155: 
 156: /// Compute the total number of passwords for a parsed mask.
 157: pub fn mask_password_count(mask: &ParsedMask) -> usize {
 158:     mask.positions.iter().map(|p| p.len()).product()
 159: }
 160: 
 161: struct MaskPasswordGenerator {
 162:     positions: Vec<Vec<u8>>,
 163:     indices: Vec<usize>,
 164:     total: usize,
 165:     generated: usize,
 166:     finished: bool,
 167: }
 168: 
 169: impl MaskPasswordGenerator {
 170:     fn new(mask: ParsedMask) -> Self {
 171:         let total = mask_password_count(&mask);
 172:         let len = mask.positions.len();
 173:         // Convert char positions to u8 once at construction
 174:         let positions = mask
 175:             .positions
 176:             .into_iter()
 177:             .map(|chars| chars.into_iter().map(|c| c as u8).collect())
 178:             .collect();
 179:         Self {
 180:             positions,
 181:             indices: vec![0; len],
 182:             total,
 183:             generated: 0,
 184:             finished: total == 0,
 185:         }
 186:     }
 187: 
 188:     fn current_password(&self) -> Vec<u8> {
 189:         self.indices
 190:             .iter()
 191:             .enumerate()
 192:             .map(|(pos, &idx)| self.positions[pos][idx])
 193:             .collect()
 194:     }
 195: }
 196: 
 197: impl Iterator for MaskPasswordGenerator {
 198:     type Item = Vec<u8>;
 199: 
 200:     fn next(&mut self) -> Option<Self::Item> {
 201:         if self.finished {
 202:             return None;
 203:         }
 204: 
 205:         let password = self.current_password();
 206:         self.generated += 1;
 207: 
 208:         if self.generated == self.total {
 209:             self.finished = true;
 210:         } else {
 211:             // Increment: rightmost position first (odometer style)
 212:             let mut carry = true;
 213:             for i in (0..self.indices.len()).rev() {
 214:                 if carry {
 215:                     self.indices[i] += 1;
 216:                     if self.indices[i] >= self.positions[i].len() {
 217:                         self.indices[i] = 0;
 218:                     } else {
 219:                         carry = false;
 220:                     }
 221:                 }
 222:             }
 223:         }
 224: 
 225:         Some(password)
 226:     }
 227: 
 228:     fn size_hint(&self) -> (usize, Option<usize>) {
 229:         let remaining = self.total - self.generated;
 230:         (remaining, Some(remaining))
 231:     }
 232: }
 233: 
