  63:                         message: "Custom charset definition ends with incomplete token '?'"
  64:                             .to_string(),
  65:                     });
  66:                 }
  67:             }
  68:         } else {
  69:             charset.push(c);
  70:         }
  71:     }
  72: 
  73:     if charset.is_empty() {
  74:         return Err(CliArgumentError {
  75:             message: "Custom charset definition is empty".to_string(),
  76:         });
  77:     }
  78: 
  79:     // deduplicate while preserving order
  80:     let mut seen = Vec::with_capacity(charset.len());
  81:     for c in charset {
  82:         if !seen.contains(&c) {
  83:             seen.push(c);
  84:         }
  85:     }
