   1: use crate::finder_errors::FinderError;
   2: use std::fs::File;
   3: use std::path::Path;
   4: use zip::result::ZipError::UnsupportedArchive;
   5: 
   6: #[derive(Clone, Debug)]
   7: pub struct AesInfo {
   8:     pub aes_key_length: usize,
   9:     pub verification_value: [u8; 2],
  10:     pub derived_key_length: usize,
  11:     pub salt: Vec<u8>,
  12: }
  13: 
  14: impl AesInfo {
  15:     pub const fn new(aes_key_length: usize, verification_value: [u8; 2], salt: Vec<u8>) -> Self {
  16:         // derive a key from the password and salt
  17:         // the length depends on the aes key length
  18:         let derived_key_length = 2 * aes_key_length + 2;
  19:         Self {
  20:             aes_key_length,
  21:             verification_value,
  22:             derived_key_length,
  23:             salt,
  24:         }
  25:     }
  26: }
  27: 
  28: pub struct ValidatedZip {
  29:     pub file_number: usize,
  30:     pub aes_info: Option<AesInfo>,
  31:     pub file_name: Option<String>,
  32: }
  33: 
  34: impl ValidatedZip {
  35:     pub const fn new(
  36:         file_number: usize,
  37:         aes_info: Option<AesInfo>,
  38:         file_name: Option<String>,
  39:     ) -> Self {
  40:         Self {
  41:             file_number,
  42:             aes_info,
  43:             file_name,
  44:         }
  45:     }
  46: }
  47: 
  48: // Check if a specific file in the archive is encrypted
  49: fn is_file_encrypted(archive: &mut zip::ZipArchive<File>, index: usize) -> bool {
  50:     matches!(
  51:         archive.by_index(index),
  52:         Err(UnsupportedArchive("Password required to decrypt file"))
  53:     )
  54: }
  55: 
  56: // Build a listing of files in the archive for diagnostics (capped at 20 entries)
  57: fn format_archive_listing(archive: &mut zip::ZipArchive<File>) -> String {
  58:     let total = archive.len();
  59:     let display_count = total.min(20);
  60:     let mut listing = format!("Archive contents ({total} files):");
  61:     for i in 0..display_count {
  62:         let name = archive.name_for_index(i).unwrap_or("<unknown>").to_string();
  63:         let is_dir = name.ends_with('/');
  64:         let encrypted = is_file_encrypted(archive, i);
  65:         let kind = if is_dir { "dir" } else { "file" };
  66:         let enc = if encrypted { ", encrypted" } else { "" };
  67:         listing.push_str(&format!("\n  [{i}] {name} ({kind}{enc})"));
  68:     }
  69:     if total > display_count {
  70:         listing.push_str(&format!("\n  ... and {} more files", total - display_count));
  71:     }
  72:     listing
  73: }
  74: 
  75: // Find the first encrypted file in the archive, returns its index
  76: fn find_first_encrypted_file(archive: &mut zip::ZipArchive<File>) -> Option<usize> {
  77:     (0..archive.len()).find(|&i| is_file_encrypted(archive, i))
  78: }
  79: 
  80: // validate that the zip requires a password
  81: pub fn validate_zip(file_path: &Path, file_number: usize) -> Result<ValidatedZip, FinderError> {
  82:     let file = File::open(file_path)?;
  83:     let mut archive = zip::ZipArchive::new(file)?;
  84: 
  85:     // Resolve the target file index
  86:     let target_index = if is_file_encrypted(&mut archive, file_number) {
  87:         file_number
  88:     } else {
  89:         // The selected file is not encrypted, try to find one that is
  90:         match find_first_encrypted_file(&mut archive) {
  91:             Some(index) => {
  92:                 let name = archive.name_for_index(index).unwrap_or("<unknown>");
  93:                 eprintln!(
  94:                     "File at index {file_number} is not encrypted, auto-selecting file at index {index} ({name})"
  95:                 );
  96:                 index
  97:             }
  98:             None => {
  99:                 return Err(FinderError::invalid_zip_error(format!(
 100:                     "no encrypted file found in archive\n{}",
 101:                     format_archive_listing(&mut archive)
 102:                 )));
 103:             }
 104:         }
 105:     };
 106: 
 107:     // At this point, target_index is guaranteed to be an encrypted file
 108:     let aes_data = archive.get_aes_verification_key_and_salt(target_index);
 109:     let file_name = archive
 110:         .name_for_index(target_index)
 111:         .map(ToString::to_string);
 112:     let aes_info = if let Some(aes_zip_info) = aes_data.expect("Archive validated before-hand") {
 113:         let aes_key_length = aes_zip_info.aes_mode.key_length();
 114:         let verification_value = aes_zip_info.verification_value;
 115:         let salt = aes_zip_info.salt;
 116:         Some(AesInfo::new(aes_key_length, verification_value, salt))
 117:     } else {
 118:         None
 119:     };
 120:     Ok(ValidatedZip::new(target_index, aes_info, file_name))
 121: }

